const treeData = $('HTTP: Fetch Repository Tree').first().json;
const commitsData = $('HTTP: Fetch Recent Commits').first().json;
const existingIssues = $('HTTP: Fetch Open INFRA Issues').first().json;
const initContext = $('Set: Initialize Scan Context').first().json;

// Build last modified map from commits
const fileLastModified = {};
const commits = Array.isArray(commitsData) ? commitsData : [];

commits.forEach(commit => {
  const date = commit.commit?.author?.date || commit.commit?.committer?.date;
  if (!date) return;

  // For each commit, we'd need to fetch files changed - simplified approach
  // Mark this commit date for tracking
});

// Get existing tech debt issue keys to avoid duplicates
const existingKeys = new Set();
const issues = existingIssues?.issues || [];
issues.forEach(issue => {
  if (issue.fields?.summary) {
    existingKeys.add(issue.fields.summary);
  }
});

// Filter source files from tree
const tree = treeData?.tree || [];
const sourceExtensions = ['.ts', '.tsx', '.js', '.jsx', '.py', '.css', '.json'];
const ignoreDirs = ['node_modules', '.git', 'dist', 'build', '.next', '__pycache__', '.claude'];

const sourceFiles = tree.filter(item => {
  if (item.type !== 'blob') return false;
  const path = item.path;

  // Skip ignored directories
  if (ignoreDirs.some(dir => path.includes(`${dir}/`))) return false;

  // Only include source files
  return sourceExtensions.some(ext => path.endsWith(ext));
});

// Categorize files for parallel scanning
const codeFiles = sourceFiles.filter(f => 
  ['.ts', '.tsx', '.js', '.jsx', '.py'].some(ext => f.path.endsWith(ext))
);

// Limit to reasonable batch for API calls
const filesToScan = codeFiles.slice(0, 50);

return {
  json: {
    scanId: initContext.scanId,
    scanDate: initContext.scanDate,
    repoOwner: initContext.repoOwner,
    repoName: initContext.repoName,
    defaultBranch: initContext.defaultBranch,
    staleFileDays: initContext.staleFileDays,
    maxFunctionLines: initContext.maxFunctionLines,
    totalSourceFiles: sourceFiles.length,
    filesToScan: filesToScan,
    existingIssueKeys: Array.from(existingKeys),
    existingIssueCount: existingKeys.size
  }
};

const context = $input.first().json;
const files = context.filesToScan || [];

// Create items for each file to fetch
return files.slice(0, 10).map(file => ({
  json: {
    filePath: file.path,
    sha: file.sha,
    size: file.size,
    repoOwner: context.repoOwner,
    repoName: context.repoName,
    defaultBranch: context.defaultBranch,
    scanId: context.scanId,
    maxFunctionLines: context.maxFunctionLines
  }
}));

const filePath = $json.filePath;
const content = $json.data || '';
const maxLines = $json.maxFunctionLines || 100;
const scanId = $json.scanId;

const issues = [];

// 1. Check for TODO/FIXME/HACK comments
const todoPatterns = [
  { pattern: /\/\/\s*TODO[:\s](.+)/gi, type: 'TODO' },
  { pattern: /\/\/\s*FIXME[:\s](.+)/gi, type: 'FIXME' },
  { pattern: /\/\/\s*HACK[:\s](.+)/gi, type: 'HACK' },
  { pattern: /#\s*TODO[:\s](.+)/gi, type: 'TODO' },
  { pattern: /#\s*FIXME[:\s](.+)/gi, type: 'FIXME' },
  { pattern: /#\s*HACK[:\s](.+)/gi, type: 'HACK' }
];

const lines = content.split('\n');
let lineNumber = 0;

for (const line of lines) {
  lineNumber++;
  for (const { pattern, type } of todoPatterns) {
    pattern.lastIndex = 0;
    const match = pattern.exec(line);
    if (match) {
      issues.push({
        category: 'comment',
        type: type,
        file: filePath,
        line: lineNumber,
        message: match[1]?.trim() || 'No description',
        severity: type === 'HACK' ? 'high' : type === 'FIXME' ? 'medium' : 'low',
        scanId: scanId
      });
    }
  }
}

// 2. Check for long functions (basic heuristic)
const functionPatterns = [
  /^\s*(async\s+)?function\s+(\w+)/,
  /^\s*(export\s+)?(async\s+)?function\s+(\w+)/,
  /^\s*(const|let|var)\s+(\w+)\s*=\s*(async\s+)?\(/,
  /^\s*(def)\s+(\w+)\s*\(/
];

let inFunction = false;
let functionStartLine = 0;
let functionName = '';
let braceCount = 0;
let functionLines = 0;

for (let i = 0; i < lines.length; i++) {
  const line = lines[i];

  if (!inFunction) {
    for (const pattern of functionPatterns) {
      const match = line.match(pattern);
      if (match) {
        inFunction = true;
        functionStartLine = i + 1;
        functionName = match[2] || match[3] || 'anonymous';
        functionLines = 1;
        braceCount = (line.match(/\{/g) || []).length - (line.match(/\}/g) || []).length;
        break;
      }
    }
  } else {
    functionLines++;
    braceCount += (line.match(/\{/g) || []).length - (line.match(/\}/g) || []).length;

    if (braceCount <= 0 || (filePath.endsWith('.py') && line.match(/^\S/) && functionLines > 1)) {
      if (functionLines > maxLines) {
        issues.push({
          category: 'complexity',
          type: 'LONG_FUNCTION',
          file: filePath,
          line: functionStartLine,
          message: `Function '${functionName}' is ${functionLines} lines (max: ${maxLines})`,
          severity: functionLines > 200 ? 'high' : 'medium',
          scanId: scanId
        });
      }
      inFunction = false;
    }
  }
}

// 3. Check for duplicate code patterns (simplified - look for repeated blocks)
const seenBlocks = new Map();
const blockSize = 5;

for (let i = 0; i < lines.length - blockSize; i++) {
  const block = lines.slice(i, i + blockSize)
    .map(l => l.trim())
    .filter(l => l.length > 0 && !l.startsWith('//'))
    .join('|');

  if (block.length > 50) {
    if (seenBlocks.has(block)) {
      const firstOccurrence = seenBlocks.get(block);
      issues.push({
        category: 'duplication',
        type: 'DUPLICATE_CODE',
        file: filePath,
        line: i + 1,
        message: `Duplicate code block found (first at line ${firstOccurrence})`,
        severity: 'low',
        scanId: scanId
      });
    } else {
      seenBlocks.set(block, i + 1);
    }
  }
}

// 4. Check for missing error handling patterns
const errorPatterns = [
  { pattern: /\.catch\(\s*\(\s*\)\s*=>\s*\{\s*\}\s*\)/g, message: 'Empty catch block' },
  { pattern: /catch\s*\([^)]*\)\s*\{\s*\}/g, message: 'Empty catch block' },
  { pattern: /\/\/\s*@ts-ignore/gi, message: '@ts-ignore suppresses type checking' },
  { pattern: /\/\/\s*eslint-disable/gi, message: 'ESLint rule disabled' }
];

for (let i = 0; i < lines.length; i++) {
  for (const { pattern, message } of errorPatterns) {
    pattern.lastIndex = 0;
    if (pattern.test(lines[i])) {
      issues.push({
        category: 'quality',
        type: 'CODE_SMELL',
        file: filePath,
        line: i + 1,
        message: message,
        severity: 'medium',
        scanId: scanId
      });
    }
  }
}

return {
  json: {
    filePath: filePath,
    linesOfCode: lines.length,
    issuesFound: issues.length,
    issues: issues
  }
};

const allResults = $input.all();

// Flatten all issues from all files
const allIssues = [];
let totalFiles = 0;
let totalLines = 0;

for (const item of allResults) {
  if (item.json.issues) {
    allIssues.push(...item.json.issues);
  }
  if (item.json.linesOfCode) {
    totalFiles++;
    totalLines += item.json.linesOfCode;
  }
}

// Group by category
const byCategory = {};
const bySeverity = { high: 0, medium: 0, low: 0 };
const byType = {};

for (const issue of allIssues) {
  byCategory[issue.category] = (byCategory[issue.category] || 0) + 1;
  bySeverity[issue.severity] = (bySeverity[issue.severity] || 0) + 1;
  byType[issue.type] = (byType[issue.type] || 0) + 1;
}

// Sort issues by severity for prioritization
const severityOrder = { high: 0, medium: 1, low: 2 };
const sortedIssues = allIssues.sort((a, b) => 
  severityOrder[a.severity] - severityOrder[b.severity]
);

// Get top priority issues for AI analysis
const topIssues = sortedIssues.slice(0, 20);

return {
  json: {
    scanId: allResults[0]?.json?.scanId || 'unknown',
    summary: {
      filesScanned: totalFiles,
      totalLines: totalLines,
      totalIssues: allIssues.length,
      byCategory: byCategory,
      bySeverity: bySeverity,
      byType: byType
    },
    topIssues: topIssues,
    allIssues: sortedIssues
  }
};

const data = $json;
const summary = data.summary;
const topIssues = data.topIssues;

const issuesList = topIssues.map((issue, i) => 
  `${i + 1}. [${issue.severity.toUpperCase()}] ${issue.type} in ${issue.file}:${issue.line}\n   ${issue.message}`
).join('\n\n');

const prompt = `You are a senior software architect reviewing tech debt in the SwjshAlgoKnife trading platform codebase.

SCAN SUMMARY:
- Files Scanned: ${summary.filesScanned}
- Total Lines: ${summary.totalLines.toLocaleString()}
- Total Issues Found: ${summary.totalIssues}

ISSUES BY SEVERITY:
- High: ${summary.bySeverity.high || 0}
- Medium: ${summary.bySeverity.medium || 0}
- Low: ${summary.bySeverity.low || 0}

ISSUES BY CATEGORY:
${Object.entries(summary.byCategory).map(([k, v]) => `- ${k}: ${v}`).join('\n')}

TOP 20 PRIORITY ISSUES:
${issuesList}

ANALYZE AND PROVIDE:

1. **Executive Summary** (2-3 sentences): Overall health assessment

2. **Critical Priorities** (max 5): Issues requiring immediate attention with:
   - Issue reference
   - Why it's critical
   - Recommended fix approach
   - Estimated effort (hours)

3. **Quick Wins** (max 5): Low-effort, high-value improvements

4. **Technical Debt Score**: Rate 1-10 (1=critical debt, 10=minimal debt)

5. **Recommended Sprint Focus**: What should the next sprint prioritize?

Respond as JSON:
{
  "executiveSummary": "string",
  "criticalPriorities": [
    {
      "issue": "string",
      "file": "string",
      "reason": "string",
      "fix": "string",
      "effortHours": number
    }
  ],
  "quickWins": [
    {
      "issue": "string",
      "benefit": "string",
      "effort": "string"
    }
  ],
  "techDebtScore": number,
  "sprintFocus": "string",
  "jiraTickets": [
    {
      "summary": "string",
      "description": "string",
      "priority": "High|Medium|Low",
      "labels": ["string"]
    }
  ]
}`;

return {
  json: {
    ...data,
    claudePrompt: prompt
  }
};

const input = $json;
let analysis;

try {
  const responseText = input.content?.[0]?.text || input.content || '';

  // Extract JSON from response
  const jsonMatch = responseText.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    analysis = JSON.parse(jsonMatch[0]);
  } else {
    throw new Error('No JSON found in response');
  }
} catch (e) {
  analysis = {
    executiveSummary: 'Unable to parse AI analysis - please review manually',
    criticalPriorities: [],
    quickWins: [],
    techDebtScore: 5,
    sprintFocus: 'Review scan results manually',
    jiraTickets: [],
    _parseError: e.message
  };
}

return {
  json: {
    scanId: input.scanId,
    summary: input.summary,
    topIssues: input.topIssues,
    allIssues: input.allIssues,
    analysis: analysis
  }
};

const data = $input.first().json;
const tickets = data.analysis?.jiraTickets || [];

// Create an item for each ticket
return tickets.map(ticket => ({
  json: {
    summary: ticket.summary,
    description: ticket.description,
    priority: ticket.priority,
    labels: [...(ticket.labels || []), 'tech-debt', 'automated-scan'],
    scanId: data.scanId
  }
}));

// Get the main scan data
const scanData = $('Code: Parse Claude Response').first().json;
const analysis = scanData.analysis;
const summary = scanData.summary;

// Count created tickets
const ticketResults = $input.all();
const createdTickets = ticketResults.filter(t => t.json?.key).length;

const debtEmoji = analysis.techDebtScore >= 7 ? ':white_check_mark:' : 
                  analysis.techDebtScore >= 4 ? ':warning:' : ':red_circle:';

return {
  json: {
    scanId: scanData.scanId,
    summary: summary,
    analysis: analysis,
    ticketsCreated: createdTickets,
    embedTitle: `Tech Debt Scan: ${scanData.scanId}`,
    embedDescription: analysis.executiveSummary,
    embedColor: analysis.techDebtScore >= 7 ? 3066993 : 
                analysis.techDebtScore >= 4 ? 16776960 : 15158332,
    debtScore: `${debtEmoji} ${analysis.techDebtScore}/10`,
    sprintFocus: analysis.sprintFocus
  }
};

const error = $json;

return {
  json: {
    workflowId: error.workflow?.id || 'unknown',
    workflowName: error.workflow?.name || 'Tech Debt Scanner',
    errorMessage: error.execution?.error?.message || 'Unknown error',
    errorNode: error.execution?.lastNodeExecuted || 'unknown',
    timestamp: new Date().toISOString(),
    executionId: error.execution?.id || 'unknown'
  }
};
